// ListSharesIter returns an iterator that iterates
// over the results of ListShares.
//
// For example:
//
//	for item, err := range c.ListSharesIter(ctx, ListSharesRequest{}) {
//	  if err != nil {
//	    return err
//	  }
//	  fmt.Println(item)
//	}
//
// Options opts are passed to each ListShares call
// made by the iterator under the hood.
//
// Callers who need custom pagination logic should use
// ListShares directly.
func (c *internalClient) ListSharesIter(ctx context.Context, req ListSharesRequest, opts ...call.Option) iter.Seq2[*ShareInfo, error] {
	return func(yield func(*ShareInfo, error) bool) {
		// Keep pagination state local to this traversal so reusing the iterator starts
		// from the original request. Reference-bearing fields remain shared and read-only.
		pageReq := req
		for {
			resp, err := c.ListShares(ctx, pageReq, opts...)
			if err != nil {
				yield(nil, err)
				return
			}
			for i := range resp.Shares {
				if !yield(&resp.Shares[i], nil) {
					return
				}
			}
			if resp.NextPageToken == nil || *resp.NextPageToken == "" {
				return
			}
			pageReq.PageToken = resp.NextPageToken
		}
	}
}

